NEW_FILES = {'tests/test_parche102.py': '"""parche-102: preguntas sin signos que empiezan por verbo; calificador sin respaldo."""\nfrom src.language import consultas\n\n\ndef test_verbo_primero_sin_signos():\n    assert consultas.canonical("es la tierra el tercer planeta") == "¿Es la tierra el tercer planeta?"\n    assert consultas.canonical("tiene la tierra alguna luna") == "¿Tiene la tierra alguna luna?"\n    assert consultas.canonical("Es un planeta.") == "Es un planeta."          # un hecho\n    assert consultas.canonical("Tiene un perro") == "Tiene un perro"          # capitalizado: hecho\n    assert consultas.canonical("hay un gato en la casa") == "hay un gato en la casa"\n'}

def main(root: Path = ROOT) -> int:
    stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S-%f")
    bk = root / ".parche_backups" / stamp
    texts, changed = {}, set()
    for rel, old, new, marca in ALL_EDITS:                              # comprobar TODO antes de escribir nada
        p = root / rel
        if not p.is_file():
            print(f"FALTA {rel}: no se toca nada."); return 1
        txt = texts[rel] if rel in texts else p.read_text(encoding="utf-8")
        if marca in txt:
            texts[rel] = txt; continue
        if txt.count(old) != 1:
            print(f"ERROR {rel}: un trozo a cambiar aparece {txt.count(old)} veces (debe ser 1): {old[:70]!r}. No se toca nada."); return 1
        texts[rel] = txt.replace(old, new); changed.add(rel)
    plan = [(root / rel, rel, texts[rel]) for rel in sorted(changed)]
    for rel, content in NEW_FILES.items():
        p = root / rel
        if not p.exists() or p.read_text(encoding="utf-8") != content:
            plan.append((p, rel, content))
    for p, rel, txt in plan:
        if p.exists():
            (bk / rel).parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(p, bk / rel)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(txt, encoding="utf-8")
        if rel.endswith(".py"):
            py_compile.compile(str(p), doraise=True)
        print(f"  escrito {rel}")
    print(f"parche-102 instalado. Copias en {bk}" if plan else "parche-102: nada que hacer.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

